def svg_card(title, left, center, right, index):
    safe=escape(title); left=escape(left); center=escape(center); right=escape(right)
    return f'''<figure class="logic-diagram mini-diagram" aria-labelledby="g102-{index}-caption"><svg viewBox="0 0 560 132" role="img" aria-labelledby="g102-{index}-title g102-{index}-desc" xmlns="http://www.w3.org/2000/svg"><title id="g102-{index}-title">{safe}</title><desc id="g102-{index}-desc">A three-stage conceptual relationship: {left}, {center}, and {right}. This is an evidence-bounded framework, not a statistic.</desc><rect x="12" y="10" width="536" height="112" rx="8" fill="#101510" stroke="#B59654" stroke-opacity=".42"/><text x="280" y="29" text-anchor="middle" font-family="Arial,sans-serif" font-size="12" fill="#B59654" letter-spacing="1.2">{safe.upper()}</text><rect x="28" y="50" width="150" height="43" rx="5" fill="#153B2A" stroke="#2E8B57"/><text x="103" y="76" text-anchor="middle" font-family="Arial,sans-serif" font-size="10" fill="#F5F0E6">{left}</text><path d="M182 71 H216" stroke="#B59654" stroke-width="1.5"/><path d="M216 71 l-8 -5 v10 z" fill="#B59654"/><rect x="205" y="50" width="150" height="43" rx="5" fill="#3C3020" stroke="#B59654"/><text x="280" y="76" text-anchor="middle" font-family="Arial,sans-serif" font-size="10" fill="#F5F0E6">{center}</text><path d="M359 71 H393" stroke="#B59654" stroke-width="1.5"/><path d="M393 71 l-8 -5 v10 z" fill="#B59654"/><rect x="382" y="50" width="150" height="43" rx="5" fill="#202B35" stroke="#7894A8"/><text x="457" y="76" text-anchor="middle" font-family="Arial,sans-serif" font-size="10" fill="#F5F0E6">{right}</text></svg><figcaption id="g102-{index}-caption" class="diagram-caption">{index}. {safe} — conceptual framework; evidence scope is stated in the prose.</figcaption></figure>'''


