def atlas_html():
    cards='\n'.join(svg_card(*row,i) for i,row in enumerate(GRAPHICS,1))
    return f'<section class="logic-atlas" aria-labelledby="atlas-title"><h3 id="atlas-title" class="section-label">Logic Atlas: Continuity Through Change</h3><p>These {len(GRAPHICS)} original SVG graphics translate the page’s reasoning into compact, printable structures. They distinguish documented evidence from interpretive frameworks and avoid treating Pashtun-wide or family-specific practices as automatically Orakzai-specific.</p><div class="atlas-grid">{cards}</div></section>'

